import pytest
from candidate import flip_case

def test_flip_case_basic():
    assert flip_case('Hello') == 'hELLO'

def test_flip_case_all_lower():
    assert flip_case('abcd') == 'ABCD'

def test_flip_case_all_upper():
    assert flip_case('ABCD') == 'abcd'

def test_flip_case_mixed():
    assert flip_case('aBcDeF') == 'AbCdEf'

def test_flip_case_empty():
    assert flip_case('') == ''

def test_flip_case_no_letters():
    assert flip_case('1234!@#') == '1234!@#'

def test_flip_case_digits_and_letters():
    assert flip_case('a1b2') == 'A1B2'

def test_flip_case_whitespace():
    assert flip_case(' Hello World ') == ' hELLO wORLD '

def test_flip_case_unicode_letters():
    assert flip_case('éÉ') == 'Éé'

def test_flip_case_german_sharp_s():
    assert flip_case('ß') == 'SS'

def test_flip_case_cyrillic():
    assert flip_case('Привет') == 'привет'

def test_flip_case_emoji_and_symbols():
    assert flip_case('😊Hello!') == '😊hELLO!'

def test_flip_case_double_flip():
    s = 'Test123'
    assert flip_case(flip_case(s)) == s

def test_flip_case_none_raises():
    with pytest.raises(AttributeError):
        flip_case(None)

def test_flip_case_int_raises():
    with pytest.raises(AttributeError):
        flip_case(123)

def test_flip_case_list_raises():
    with pytest.raises(AttributeError):
        flip_case([1, 2, 3])

def test_flip_case_subclass_string():
    class MyStr(str):
        pass
    s = MyStr('Foo')
    assert flip_case(s) == 'fOO'

def test_flip_case_greek_letters():
    assert flip_case('ΑβΓ') == 'αΒγ'

def test_flip_case_non_case_mapping():
    assert flip_case('あ') == 'あ'

def test_flip_case_micro_sign():
    assert flip_case('µ') == 'µ'

def test_flip_case_single_character():
    assert flip_case('x') == 'X'

def test_flip_case_bytes_input():
    assert flip_case(b'Hello') == b'hELLO'
